from shiny import ui, reactive, App, render
from datetime import datetime
from faicons import icon_svg
import json
from pathlib import Path

import load_data
from season import Season
from breakdown import Breakdown
from ui_elements import (
    ui_season_info,
    ui_breakdown,
    ui_credits,
    ui_imgs,
    ui_update_inventory,
    FONT_FAMILY,
)

app_ui = ui.page_fluid(
    ui.input_dark_mode(),
    ui.tags.link(
        rel="stylesheet", href=f"https://fonts.googleapis.com/css2?family={FONT_FAMILY}"
    ),
    ui.tags.style(f"body {{ font-family: '{FONT_FAMILY}'}}"),
    ui.tags.style(
        f".tooltip {{ background-color: black; font-family: '{FONT_FAMILY}'}}"
    ),
    ui.row(
        ui.panel_title("Imaginarium Theater"),
        ui.div(
            ui.input_selectize(
                id="selected_season",
                label="",
                choices=load_data.season_labels(),
                selected=datetime.today().strftime("%B %Y"),
                width="200px",
            )
        ),
        align="center",
    ),
    ui_season_info(),
    ui.p(),
    ui.row(
        ui.panel_title("Character Inventory"),
        ui.row(
            ui.column(
                4,
                ui.div(
                    ui.tooltip(
                        ui.input_file(
                            id="import_inventory",
                            label="Import Inventory",
                            button_label=icon_svg("upload"),
                            accept=".json",
                            placeholder="Click to upload .json file",
                        ),
                        "Genshin Open Object Definition (GOOD) format is accepted, "
                        + "characters under level 70 are automatically excluded",
                        placement="bottom",
                    )
                ),
                align="center",
            ),
            ui.column(
                4,
                ui.input_checkbox(
                    id="include_traveler",
                    label="Include Traveler",
                    value=True,
                ),
                ui.p(),
                ui.input_selectize(
                    id="traveler_name",
                    label="",
                    choices=["Aether", "Lumine"],
                    width="120px",
                ),
            ),
            ui.column(
                2,
                "Export Inventory",
                ui.p(),
                ui.div(
                    ui.tooltip(
                        ui.download_button(
                            id="export_inventory", label=icon_svg("download")
                        ),
                        "Exports to a simple array .json usable for this page",
                        placement="bottom",
                    )
                ),
                align="center",
            ),
            ui.column(
                2,
                "Clear Inventory",
                ui.p(),
                ui.div(
                    ui.tooltip(
                        ui.input_action_button(
                            id="clear_inventory", label=icon_svg("eraser")
                        ),
                        "Clear characters in box",
                        placement="bottom",
                    )
                ),
                align="center",
            ),
        ),
        ui.input_selectize(
            id="character_inventory",
            label="Type in box to search for character names",
            choices=load_data.character_names(),
            multiple=True,
            width="100%",
        ),
        ui.p(),
        ui.panel_title("Character Requirement Counter"),
        ui.output_text(id="highest_difficulty_text"),
        ui.output_text(id="next_difficulty_text"),
        ui.p(),
        ui.output_text(id="eligible_characters_text"),
        ui.p(),
        ui_breakdown(),
        ui.p(),
        ui_credits(),
        align="center",
    ),
    title="Imaginarium Theater",
)


def server(input, output, session):
    @render.ui
    def selected_season_alt_cast_elements() -> ui.TagList:
        selected_img_paths = selected_season().get_element_imgs()
        return ui_imgs(selected_img_paths)

    @render.ui
    def selected_season_op_characters() -> ui.TagList:
        selected_img_paths = selected_season().get_op_character_imgs()
        return ui_imgs(selected_img_paths)

    @render.ui
    def selected_season_special_invites() -> ui.TagList:
        selected_img_paths = selected_season().get_special_invite_imgs()
        return ui_imgs(selected_img_paths)

    @reactive.calc
    def selected_season() -> Season:
        return Season(input.selected_season())

    @render.download(
        filename=(f"inventory_{datetime.today().strftime("%Y-%m-%d")}.json")
    )
    def export_inventory():
        yield json.dumps(character_inventory()).encode("utf-8")

    @reactive.effect
    def clear_inventory():
        input.clear_inventory()
        ui.update_selectize(id="character_inventory", selected=[])

    @reactive.calc
    def character_inventory() -> list[str]:
        inventory = list(input.character_inventory())
        if input.include_traveler():
            inventory += ["Traveler"]
        return inventory

    @reactive.effect
    def import_inventory():
        file = input.import_inventory()
        if file is not None:
            with open(file[0]["datapath"], "r") as f:
                inventory = json.load(f)
            ui_update_inventory(ui, inventory)

    @render.text
    def highest_difficulty_text() -> str:
        count = elig_char_breakdown().n_chars()
        highest_tier = selected_season().highest_tier(count)
        if highest_tier is None:
            text = f"You do not have enough characters to participate this season."
        else:
            text = f"The highest difficulty you can challenge this season is {highest_tier} Mode."
        return text

    @render.text
    def next_difficulty_text() -> str:
        count = elig_char_breakdown().n_chars()
        next_tier = selected_season().next_tier(count)
        if next_tier is None:
            text = " You have reached the highest difficulty this season."
        else:
            increment = next_tier["increment"]
            suffix = "s" if increment > 1 else ""
            text = f" You need {next_tier["increment"]} more character{suffix} "
            text += f"to challenge {next_tier["name"]} Mode."
        return text

    @reactive.calc
    def elig_char_breakdown() -> Breakdown:
        return selected_season().get_elig_char_breakdown_in(
            character_inventory(), input.traveler_name()
        )

    @render.text
    def eligible_characters_text() -> str:
        count = elig_char_breakdown().n_chars()
        return f"You have {count} eligible characters this season:"

    @render.text
    def breakdown_element_1_text() -> str:
        count = elig_char_breakdown().n_chars_in_section("element_1")
        return f"{count} from {selected_season().alt_cast_elements[0]}"

    @render.ui
    def breakdown_element_1_imgs() -> ui.TagList:
        return elig_char_breakdown().ui_imgs_in_section("element_1")

    @render.text
    def breakdown_element_2_text() -> str:
        count = elig_char_breakdown().n_chars_in_section("element_2")
        return f"{count} from {selected_season().alt_cast_elements[1]}"

    @render.ui
    def breakdown_element_2_imgs() -> ui.TagList:
        return elig_char_breakdown().ui_imgs_in_section("element_2")

    @render.text
    def breakdown_element_3_text() -> str:
        count = elig_char_breakdown().n_chars_in_section("element_3")
        return f"{count} from {selected_season().alt_cast_elements[2]}"

    @render.ui
    def breakdown_element_3_imgs() -> ui.TagList:
        return elig_char_breakdown().ui_imgs_in_section("element_3")

    @render.text
    def breakdown_op_text() -> str:
        count = elig_char_breakdown().n_chars_in_section("op")
        return f"{count} from Opening Characters"

    @render.ui
    def breakdown_op_imgs() -> ui.TagList:
        return elig_char_breakdown().ui_imgs_in_section("op")

    @render.text
    def breakdown_special_invite_text() -> str:
        count = elig_char_breakdown().n_chars_in_section("special_invites")
        return f"{count} from Special Invitations"

    @render.ui
    def breakdown_special_invite_imgs() -> ui.TagList:
        return elig_char_breakdown().ui_imgs_in_section("special_invites")

    @render.text
    def breakdown_traveler_text() -> str:
        count = elig_char_breakdown().n_chars_in_section("traveler")
        cluding = "including" if input.include_traveler() else "excluding"
        return f"{count} from {cluding} {input.traveler_name()}"

    @render.ui
    def breakdown_traveler_imgs() -> ui.TagList:
        return elig_char_breakdown().ui_imgs_in_section("traveler")


app = App(app_ui, server, static_assets=Path(__file__).parent / "www")

from shiny import ui
from ui_elements import ui_imgs


class Breakdown:
    sections = [
        *[f"element_{i+1}" for i in range(3)],
        "op",
        "special_invites",
        "traveler",
    ]

    def __init__(self, d: dict):
        self.d = d

    def n_chars(self) -> int:
        return sum([self.n_chars_in_section(s) for s in self.d])

    def n_chars_in_section(self, section: str) -> int:
        return len(self.d[section]["characters"]) if section in self.d else 0

    def ui_imgs_in_section(self, section: str, width: str = "50px") -> ui.TagList:
        if section in self.d:
            selected_imgs = self.d[section]["img_names_and_paths"]
            return ui_imgs(selected_imgs, width=width)
        else:
            return ui.TagList()

import pandas as pd
from pathlib import Path
from datetime import datetime, date

HOMDGCAT_RES_PATH = "https://homdgcat.wiki/homdgcat-res"
HOMDGCAT_ELEM_IMG_PATH = f"{HOMDGCAT_RES_PATH}/Csxylic"
HOMDGCAT_CHAR_IMG_PATH = f"{HOMDGCAT_RES_PATH}/Avatar"


def file_path(path: str) -> str:
    return Path(__file__).parent / path


def characters() -> pd.DataFrame:
    return pd.read_csv(file_path("characters.csv"))


def character_names() -> list[str]:
    return characters()["character"].tolist()


def character_keys() -> dict:
    return {n.replace(" ", ""): n for n in character_names()}


def element_img_paths() -> dict:
    elements = pd.unique(characters()["element"])
    elem_label = element_label()
    img_paths = {e: f"{HOMDGCAT_ELEM_IMG_PATH}/{elem_label[e]}.png" for e in elements}
    return img_paths


def element_label(invert: bool = False) -> dict[str]:
    elements = {
        "Electro": "Elec",
        "Anemo": "Wind",
        "Cryo": "Ice",
        "Pyro": "Fire",
        "Geo": "Rock",
        "Hydro": "Water",
        "Dendro": "Grass",
    }
    if invert:
        elements = {v: k for k, v in elements.items()}
    return elements


def character_id_to_name() -> dict:
    character_df = characters()
    ids = character_df["id"].tolist()
    names = character_df["character"].tolist()
    return {i: n for i, n in zip(ids, names)}


def character_img_paths() -> dict:
    character_df = characters()
    names = character_df["character"].tolist()
    img_paths = [
        f"{HOMDGCAT_CHAR_IMG_PATH}/{path}" for path in character_df["img_path"]
    ]
    return {n: p for n, p in zip(names, img_paths)}


def traveler_img_path(player_choice: str) -> str:
    if player_choice == "Aether":
        return f"{HOMDGCAT_CHAR_IMG_PATH}/UI_AvatarIcon_PlayerBoy.png"
    elif player_choice == "Lumine":
        return f"{HOMDGCAT_CHAR_IMG_PATH}/UI_AvatarIcon_PlayerGirl.png"


def season_labels() -> list[str]:
    season_dates = seasons()["date"].tolist()
    return [datetime.strftime(d, "%B %Y") for d in season_dates]


def seasons() -> list[date]:
    seasons = pd.read_csv(file_path("seasons.csv"), dtype=str)
    seasons["date"] = [datetime.strptime(d, "%Y-%m-%d").date() for d in seasons["date"]]
    return seasons

from datetime import datetime
from breakdown import Breakdown
import load_data
import pandas as pd


class Season:
    def __init__(self, date_label: str):
        self.date = datetime.strptime(date_label, "%B %Y").date()
        seasons = load_data.seasons()
        selected_season = seasons[seasons["date"] == self.date].melt(
            id_vars=["date"], var_name="field"
        )
        self.alt_cast_elements = Season._pull_alt_cast_elements_from(selected_season)
        self.special_invites = Season._pull_special_invites_from(selected_season)
        self.op_characters = Season._pull_op_characters_from(selected_season)

    def _pull_alt_cast_elements_from(df: pd.DataFrame) -> list[str]:
        return Season._df_field_to_list(df, "alt_cast_element")

    def _pull_special_invites_from(df: pd.DataFrame) -> list[str]:
        return Season._df_field_to_list(df, "special_invite")

    def _pull_op_characters_from(df: pd.DataFrame) -> list[str]:
        return Season._df_field_to_list(df, "op_character")

    def _df_field_to_list(df: pd.DataFrame, field_name: str) -> list[str]:
        return df[df["field"].str.contains(field_name)]["value"].tolist()

    def get_element_imgs(self) -> tuple[str, str]:
        img_paths = load_data.element_img_paths()
        selected_paths = [img_paths[e] for e in self.alt_cast_elements]
        return zip(self.alt_cast_elements, selected_paths)

    def get_op_character_imgs(self) -> tuple[str, str]:
        return Season._char_imgs(self.op_characters)

    def get_special_invite_imgs(self) -> tuple[str, str]:
        return Season._char_imgs(self.special_invites)

    def get_elig_char_breakdown_in(
        self, inventory: list[str], traveler_name: str = "Aether"
    ) -> Breakdown:
        d = {}
        self._add_element_sections_to_dict(d, inventory)
        self._add_op_and_special_invite_sections_to_dict(d, inventory)
        if "Traveler" in inventory:
            Season._add_traveler_section_to_dict(d, traveler_name)
        return Breakdown(d)

    def _add_element_sections_to_dict(self, d: dict, inventory: list[str]):
        characters = load_data.characters()
        chars_from_elements = [
            characters[
                characters["character"].isin(inventory) & (characters["element"] == e)
            ]["character"].tolist()
            for e in self.alt_cast_elements
        ]
        element_section = {
            f"element_{i+1}": {
                "characters": chars,
                "img_names_and_paths": Season._char_imgs(chars),
            }
            for i, chars in enumerate(chars_from_elements)
            if len(chars) > 0
        }
        d.update(element_section)

    def _add_op_and_special_invite_sections_to_dict(
        self, d: dict, inventory: list[str]
    ):
        chars_from_op = [c for c in self.op_characters if c not in inventory]
        chars_from_special_invite = [c for c in self.special_invites if c in inventory]
        sections_and_characters = zip(
            ["op", "special_invites"],
            [chars_from_op, chars_from_special_invite],
        )
        character_sections = {
            section: {
                "characters": chars,
                "img_names_and_paths": Season._char_imgs(chars),
            }
            for section, chars in sections_and_characters
            if len(chars) > 0
        }
        d.update(character_sections)

    def _add_traveler_section_to_dict(d: dict, traveler_name: str = "Aether"):
        traveler_section = {
            "traveler": {
                "characters": ["Traveler"],
                "img_names_and_paths": Season._char_imgs(["Traveler"], traveler_name),
            }
        }
        d.update(traveler_section)

    def _char_imgs(characters: list[str], traveler_name: str = "Aether"):
        img_paths = load_data.character_img_paths()
        selected_img_names = [c for c in characters if c != "Traveler"]
        selected_img_paths = [img_paths[n] for n in selected_img_names]

        if "Traveler" in characters:
            selected_img_names += [traveler_name]
            selected_img_paths += [load_data.traveler_img_path(traveler_name)]

        return zip(selected_img_names, selected_img_paths)

    def highest_tier(self, n_chars: int) -> str | None:
        tier_names, tier_counts = self.get_tier_names_and_counts()
        valid_tiers = [name for name, i in zip(tier_names, tier_counts) if n_chars >= i]
        if len(valid_tiers) > 0:
            return valid_tiers[-1]
        else:
            return None

    def next_tier(self, n_chars: int) -> dict | None:
        tier_names, tier_counts = self.get_tier_names_and_counts()
        next_names = [name for name, i in zip(tier_names, tier_counts) if n_chars < i]
        next_increments = [i - n_chars for i in tier_counts if n_chars < i]
        if len(next_names) > 0:
            return {"name": next_names[0], "increment": next_increments[0]}
        else:
            return None

    def get_tier_names_and_counts(self) -> tuple[list[int], list[str]]:
        tier_counts = self.get_tier_counts()
        tier_names = self.get_tier_names(tier_counts)
        return tier_names, tier_counts

    def get_tier_counts(self) -> list[int]:
        if self.date < datetime(2024, 9, 1).date():
            return [10, 14, 18]
        elif self.date < datetime(2025, 10, 1).date():
            return [8, 12, 16, 22]
        else:
            return [8, 12, 16, 22, 28]

    def get_tier_names(self, tier_counts: list[int]) -> list[str]:
        tiers = ["Easy", "Normal", "Hard", "Visionary", "Lunar"]
        return tiers[0 : len(tier_counts)]

from breakdown import Breakdown


def test_n_chars():
    assert _make_test_breakdown().n_chars() == 6


def test_n_chars_in_section():
    test_result = [
        _make_test_breakdown().n_chars_in_section(s) for s in Breakdown.sections
    ]
    expected_result = [1, 0, 2, 3, 0, 0]
    assert test_result == expected_result


def _make_test_breakdown() -> Breakdown:
    return Breakdown(
        {
            "element_1": {"characters": ["Kaeya"]},
            "element_3": {"characters": ["Yanfei", "Gaming"]},
            "op": {"characters": ["Keqing", "Furina", "Ororon"]},
        }
    )

from ui_elements import _convert_GOOD_to_list


def test_convert_GOOD_to_list():
    test_json = {"characters": [{"key": "TravelerGeo", "level": 70}]}
    assert _convert_GOOD_to_list(test_json) == ["Traveler"]

    test_json = {"characters": [{"key": "TravelerElectro", "level": 69}]}
    assert _convert_GOOD_to_list(test_json) == []

    test_json = {
        "characters": [
            {"key": "TravelerDendro", "level": 70},
            {"key": "TravelerAnemo", "level": 70},
        ]
    }
    assert _convert_GOOD_to_list(test_json) == ["Traveler"]

    test_json = {
        "characters": [
            {"key": "TravelerHydro", "level": 70},
            {"key": "TravelerPyro", "level": 69},
        ]
    }
    assert _convert_GOOD_to_list(test_json) == ["Traveler"]

    test_json = {
        "characters": [
            {"key": "KamisatoAyaka", "level": 70},
            {"key": "KaedeharaKazuha", "level": 69},
            {"key": "KukiShinobu", "level": 70},
        ]
    }
    expected_result = ["Kamisato Ayaka", "Kuki Shinobu"]
    assert _convert_GOOD_to_list(test_json) == expected_result
